// js/lang/cie/runtime/VmNativeFunction.js
var VmNativeFunction = class {
  constructor(name, jsFunction) {
    this.name = name;
    this.nativeFn = jsFunction;
  }
};

// js/lang/cie/runtime/Vm.js
var Vm = class {
  constructor(config, rpc) {
    this.config = config;
    this.rpc = rpc;
    this.scope = null;
    this.rpcFunction = new VmNativeFunction("rpc", rpc);
    this.rootScope = new VmScope(null);
    this.rootScope.declareConstant("Rpc", VmValue.ofCallable(this.rpcFunction));
  }
  async run(initialCallable) {
    this.scope = new VmScope(initialCallable, this.rootScope);
    try {
      while (true) {
        const nextScope = this.scope.run();
        if (typeof nextScope === "function") {
          const result = await nextScope(this);
          this.scope.push(result);
        } else if (nextScope instanceof VmNativeScope) {
          const result = await nextScope.nativeFn(...nextScope.args);
          this.scope.push(result);
        } else if (nextScope.callable) {
          this.scope = nextScope;
        } else {
          break;
        }
      }
    } catch (e2) {
      console.log(e2);
      if (!(this.scope && e2 instanceof UserCodeError2)) throw e2;
      const ref = e2.ref ?? this.scope.callable.getInstruction(this.scope.pc).ref;
      throw new UserCodeError2(e2.message, ref);
    }
  }
};

// js/lang/cie/parser/Parser.js
