var initFlag = false;
function addModule(filename, code) {
  if (!Sk.builtinFiles) Sk.builtinFiles = {};
  if (!Sk.builtinFiles.files) Sk.builtinFiles.files = {};
  Sk.builtinFiles.files[`src/lib/${filename}`] = code;
  Sk.builtinFiles.files[filename] = code;
}
function readFile(filename) {
  const files = Sk.builtinFiles?.files;
  if (!files) throw new Error("No built in files!");
  const content = files[filename] ?? null;
  if (content === null) throw new Error();
  return content;
}
async function runSkulpt(code, promoteGlobals = false) {
  await Sk.misceval.asyncToPromise(function() {
    const result = Sk.importMainWithBody("<stdin>", false, code, true);
    return result;
  });
  if (promoteGlobals) {
    for (const [key, value] of Object.entries(Sk.globals)) {
      if (!key.startsWith("_")) Sk.builtins[key] = value;
    }
  }
}
async function runUserCode2(filepath, code, config, rpc) {
  Sk.configure({
    __future__: Sk.python3,
    async: true,
    read: readFile,
    output(text) {
      const promise = rpc("output", Sk.ffi.remapToJs(text));
      return Sk.misceval.promiseToSuspension(promise);
    },
    err(text) {
      const promise = rpc("output", Sk.ffi.remapToJs(text));
      return Sk.misceval.promiseToSuspension(promise);
    }
  });
  Sk.builtins.rpc = new Sk.builtin.func(function(name, ...args) {
    name = Sk.ffi.remapToJs(name);
    args = args.map((a) => Sk.ffi.remapToJs(a));
    const promise = rpc(name, ...args).then((result) => {
      return Sk.ffi.remapToPy(result);
    });
    return Sk.misceval.promiseToSuspension(promise);
  });
  try {
    if (!initFlag) {
      addModule("io.py", io);
      await runSkulpt(standardPreludeOnce, true);
      initFlag = true;
    }
    await runSkulpt(standardPreludeEach, true);
    await runSkulpt(code, !!config.isPrelude);
  } catch (err) {
    const traceback = err.traceback[0];
    const isMain = traceback.filename?.startsWith("<stdin>");
    const filename = isMain ? filepath : traceback.filename;
    const ref = new Ref(filename, traceback.lineno);
    throw new UserCodeError2(err.toString(), ref);
  }
}

